/// Localization entry point for the app.
///
/// The string table is generated by `flutter gen-l10n` from the ARB files in
/// this directory (see `l10n.yaml`) and committed as
/// `app_localizations_generated.dart` plus one file per locale. This file is
/// hand-maintained and only:
/// - re-exports the generated `AppLocalizations` so callers import a single
///   stable path (`package:lexigo/l10n/l10n.dart`);
/// - adds the `context.l10n` shorthand used across the UI.
library;

// Flutter imports:
import 'package:flutter/widgets.dart';

// Project imports:
import 'app_localizations_generated.dart';

export 'app_localizations_generated.dart';

/// Convenience access to the app's localized strings.
extension AppLocalizationsBuildContext on BuildContext {
  /// Localized strings for the current locale.
  AppLocalizations get l10n => AppLocalizations.of(this)!;
}
